import { writeFileSync } from 'node:fs';
const cases = [];
for (let i = 0; i < 4; i++) cases.push('SELECT 1 *//* ; SELECT 2');
for (let i = 0; i < 2; i++) cases.push('SELECT /* unterminated; SELECT 2');
cases.push("SELECT 'unterminated; SELECT 2");
cases.push('SELECT 1 *//* ; SELECT 2');
writeFileSync('/workspace/tmpc/b4.json', JSON.stringify(cases, null, 1) + '\n');

// whitespace-class discriminator: ";" + WS + "-- c\n" + "SELECT 2"
// absorbed  -> ['SELECT 1;<WS>-- c', 'SELECT 2']
// not absorbed -> ['SELECT 1;', '-- c\nSELECT 2']
const cps = [
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20,
  0x1c, 0x1d, 0x1e, 0x1f,
  0x85, 0xa0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
  0x180e, 0x200b, 0xfeff, 0x00b7, 0x0007, 0x0000, 0x001b
];
const ws = cps.map(c => 'SELECT 1;' + String.fromCodePoint(c) + '-- c\nSELECT 2');
ws.push('SELECT 1;\r\n-- c\nSELECT 2');
ws.push('SELECT 1;\n\r-- c\nSELECT 2');
writeFileSync('/workspace/tmpc/b5.json', JSON.stringify(ws, null, 1) + '\n');
writeFileSync('/workspace/tmpc/b5.cps.json', JSON.stringify(cps.map(c => c.toString(16))) + '\n');

