import { writeFileSync } from 'node:fs';
const prefixes = ['+','-','*','/','%','@','#','^','&','|','~','!','<','>','=',':','?','.',',','(',')','[',']',';','$','_','a','1','\\','"x"',"'x'",'`x`','  '];
const cases = [];
for (const p of prefixes) cases.push('SELECT 1 ' + p + '# c; SELECT 2');
for (const p of prefixes) cases.push('SELECT 1 ' + p + '-- c; SELECT 2');
// isolate the '-#' anomaly
cases.push('SELECT 1 -# ; SELECT 2');
cases.push('SELECT 1 -#; SELECT 2');
cases.push('SELECT 1 -# x; SELECT 2');
cases.push('SELECT 1 -#x; SELECT 2');
cases.push('SELECT 1 - # c; SELECT 2');
cases.push('SELECT 1 -+# c; SELECT 2');
cases.push('SELECT 1 +-# c; SELECT 2');
cases.push('SELECT 1 --# c; SELECT 2');
writeFileSync('/workspace/tmpc/b8.json', JSON.stringify(cases, null, 1) + '\n');

import { writeFileSync } from 'node:fs';
const chars = [];
for (let c = 0x21; c <= 0x7e; c++) chars.push(String.fromCharCode(c));
const a = [], b = [];
for (const p of chars) a.push('SELECT 1 ' + p + '# c; SELECT 2');
for (const p of chars) b.push('SELECT 1 ' + p + '-- c; SELECT 2');
writeFileSync('/workspace/tmpc/b9a.json', JSON.stringify(a, null, 1) + '\n');
writeFileSync('/workspace/tmpc/b9b.json', JSON.stringify(b, null, 1) + '\n');
const extra = [
  'SELECT 1 -@# c; SELECT 2',
  'SELECT 1 -/# c; SELECT 2',
  'SELECT 1 -%# c; SELECT 2',
  'SELECT 1 -^# c; SELECT 2',
  'SELECT 1 -&# c; SELECT 2',
  'SELECT 1 -|# c; SELECT 2',
  'SELECT 1 -## c; SELECT 2',
  'SELECT 1 @-# c; SELECT 2',
  'SELECT 1 /-# c; SELECT 2',
  'SELECT 1 %-# c; SELECT 2',
  'SELECT 1 ^-# c; SELECT 2',
  'SELECT 1 --@ c; SELECT 2',
  'SELECT 1 -+-- c; SELECT 2',
  'SELECT 1 @-- c\n; SELECT 2',
  'SELECT 1 -#-- c; SELECT 2',
  'SELECT 1 -#/* c; */ SELECT 2'
];
writeFileSync('/workspace/tmpc/b9c.json', JSON.stringify(extra, null, 1) + '\n');

